uint32_t spp_ddr_init(CdoSequence * seq, uint32_t cfg) {
    uint32_t * p;
    switch (cfg) {
    case 1:
        p = ddr_config_data;
        break;

    case 2:
        p = ddr_config_data2;
        break;

    default:
        return 1;
    }
    cdocmd_add_comment(seq, "Start SPP DDR initialization");
    for (;;) {
        uint32_t cmd = *p++;
        switch (cmd) {
        case CMD_MASK_POLL:
            cdocmd_add_mask_poll(seq, p[0], p[1], p[2], p[3], 0);
            p += 4;
            break;

        case CMD_MASK_WRITE:
            cdocmd_add_mask_write(seq, p[0], p[1], p[2]);
            p += 3;
            break;

        case CMD_WRITE:
            cdocmd_add_write(seq, p[0], p[1]);
            p += 2;
            break;

        case CMD_END:
            cdocmd_add_comment(seq, "Finish SPP DDR initialization");
            return 0;
        }
    }
}
